import { uniqueName, expect, sample, test } from "../../fixtures";

test.describe("Review vendors", () => {
  test(
    "submitting with missing documents lists what is missing",
    { tag: "@REV-02" },
    async ({ apiAs }) => {
      // Arrange: a member signs in and creates a draft vendor
      const member = await apiAs("member");
      const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV02 Vendor"),
          category: "services",
          contact_email: `rev02-${suffix}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      // Arrange: upload only a w9 document and wait for its extraction to finish
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n%REV-02 sample w9\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            expect(response.status()).toBe(200);
            return (await response.json()).status as string;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      // Act: submit the vendor for review
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert: conflict with the documents_incomplete error code
      expect(submitResponse.status()).toBe(409);
      const body = await submitResponse.json();
      expect(body.error.code).toBe("documents_incomplete");

      // Assert: the error lists the missing kinds
      const serialized = JSON.stringify(body);
      expect(serialized).toContain("contract");
      expect(serialized).toContain("insurance_certificate");
    },
  );
});
